//
// Layout matches reSID wave.cc model_wave: tables are indexed by the top 12
// accumulator bits (for P_T: after ring-mod MSB substitution) and store the
// 12-bit waveform-DAC input, i.e. the 8-bit OSC3 sample << 4 (low 4 bits
// grounded). Tables cover the tri/saw core of each combination; the pulse
// rail and noise mask AND in at the selector (sid-voice.js).

// Base64 decoder — AudioWorkletGlobalScope has no atob(), so decode by hand.
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const B64REV = (() => {
  const r = new Int8Array(128).fill(-1);
  for (let i = 0; i < 64; i++) r[B64.charCodeAt(i)] = i;
  return r;
})();

// Decode base64 → Uint16Array of sample<<4 (the 12-bit DAC input values).
function decodeTable(b64) {
  const out = new Uint16Array(4096);
  let acc = 0, bits = 0, n = 0;
  for (let i = 0; i < b64.length; i++) {
    const v = B64REV[b64.charCodeAt(i)];
    if (v < 0) continue; // padding '='
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out[n++] = ((acc >> bits) & 0xFF) << 4;
    }
  }
  if (n !== 4096) throw new Error('sid-wavetables: bad payload length ' + n);
  return out;
}

const PAYLOAD = {
  ST_6581: '',
  PT_6581: '',
  PS_6581: '',
  PST_6581: '',
  ST_8580: '',
  PT_8580: '',
  PS_8580: '',
  PST_8580: '',
};

export const WAVETABLES_6581 = {
  ST: decodeTable(PAYLOAD.ST_6581),
  PT: decodeTable(PAYLOAD.PT_6581),
  PS: decodeTable(PAYLOAD.PS_6581),
  PST: decodeTable(PAYLOAD.PST_6581),
};
export const WAVETABLES_8580 = {
  ST: decodeTable(PAYLOAD.ST_8580),
  PT: decodeTable(PAYLOAD.PT_8580),
  PS: decodeTable(PAYLOAD.PS_8580),
  PST: decodeTable(PAYLOAD.PST_8580),
};
